import sys

def main():
    data = sys.stdin.buffer.read().split()
    n = int(data[0]); m = int(data[1])
    lo = 1
    hi = m
    out = []
    p = 2
    for _ in range(n):
        x = int(data[p]); w = data[p + 1]; p += 2
        if w == b"higher":
            if x + 1 > lo:
                lo = x + 1
        elif w == b"lower":
            if x - 1 < hi:
                hi = x - 1
        else:
            if x > lo:
                lo = x
            if x < hi:
                hi = x
        out.append(hi - lo + 1 if hi >= lo else 0)
    sys.stdout.write("\n".join(map(str, out)) + "\n")

main()
